})






const open = async (type: 'create' | 'update', id?: EntityId, defaults?: Partial<BoxunHistoricalWeatherFormData>) => {

  formType.value = type
  editingId.value = id

  dialogTitle.value = type === 'create' ? '新增历史天气' : '修改历史天气'
  formData.value = { ...initialFormData(), ...defaults }
  formLoading.value = true
  dialogVisible.value = true
  try {


