}
defineExpose({ open })


const submitForm = async () => {
  if (formLoading.value) return



  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) {

    return
  }
  const inputFields = formType.value === 'create' ? ['weatherDate', 'week', 'maximumTemperature', 'lowestTemperature', 'morning', 'afternoon', 'windDirection', 'airQualityIndex', 'accumulatedTemperature', 'areaId', 'areaType'] : ['id', 'weatherDate', 'week', 'maximumTemperature', 'lowestTemperature', 'morning', 'afternoon', 'windDirection', 'airQualityIndex', 'accumulatedTemperature', 'areaId', 'areaType']
  const input = Object.fromEntries(inputFields.map((key) => [key, formData.value[key]]))
  if ('weatherDate' in input) input.weatherDate = formData.value.weatherDate ? String(formData.value.weatherDate).replace(' ', 'T') : null
  formLoading.value = true
  try {
    if (formType.value === 'create') {
      await BoxunHistoricalWeatherApi.createBoxunHistoricalWeather(input)
